import{_ as d}from"./chunks/prontera-north.9N94lC28.js";import{c as a,Q as r,j as e,m as h}from"./chunks/framework.BPKcPtvA.js";const c=JSON.parse('{"title":"属性（STAT）系统详解","description":"RO3六大基础属性全解析：STR/AGI/VIT/INT/DEX/LUK的作用、收益和加点策略。","frontmatter":{"title":"属性（STAT）系统详解","description":"RO3六大基础属性全解析：STR/AGI/VIT/INT/DEX/LUK的作用、收益和加点策略。","lastUpdated":true},"headers":[],"relativePath":"guide/stats.md","filePath":"guide/stats.md","lastUpdated":1780230058000}'),o={name:"guide/stats.md"};function l(n,t,s,i,b,g){return r(),e("div",null,[...t[0]||(t[0]=[h('<h1 id="属性-stat-系统详解" tabindex="-1">属性（STAT）系统详解 <a class="header-anchor" href="#属性-stat-系统详解" aria-label="Permalink to &quot;属性（STAT）系统详解&quot;">​</a></h1><p><img src="'+d+`" alt="RO3 属性系统"></p><p>RO3继承了RO经典的属性系统，六项基础属性的合理分配决定了角色的发展方向。</p><h2 id="六项基础属性" tabindex="-1">六项基础属性 <a class="header-anchor" href="#六项基础属性" aria-label="Permalink to &quot;六项基础属性&quot;">​</a></h2><h3 id="str-力量" tabindex="-1">STR（力量） <a class="header-anchor" href="#str-力量" aria-label="Permalink to &quot;STR（力量）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>主要影响</strong></td><td>物理攻击力、负重上限</td></tr><tr><td><strong>适合职业</strong></td><td>剑士、刺客、商人</td></tr><tr><td><strong>加点优先级</strong></td><td>物理输出职业 &gt; 坦克 &gt; 法系职业</td></tr><tr><td><strong>每点收益</strong></td><td>ATK +2, 负重 +30</td></tr></tbody></table><p><strong>适合场景</strong>：</p><ul><li>物理近战输出（骑士、刺客）</li><li>需要负重的职业（商人）</li><li>追求普攻伤害的BD</li></ul><h3 id="agi-敏捷" tabindex="-1">AGI（敏捷） <a class="header-anchor" href="#agi-敏捷" aria-label="Permalink to &quot;AGI（敏捷）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>主要影响</strong></td><td>攻击速度、闪避率</td></tr><tr><td><strong>适合职业</strong></td><td>刺客、弓箭手、剑士</td></tr><tr><td><strong>加点优先级</strong></td><td>攻速职业 &gt; 闪避坦 &gt; 其他</td></tr><tr><td><strong>每点收益</strong></td><td>攻速 +1%, 闪避 +1</td></tr></tbody></table><p><strong>适合场景</strong>：</p><ul><li>追求攻速的暴击流（刺客、弓箭手）</li><li>闪避坦克</li><li>挂机自动战斗</li></ul><h3 id="vit-体力" tabindex="-1">VIT（体力） <a class="header-anchor" href="#vit-体力" aria-label="Permalink to &quot;VIT（体力）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>主要影响</strong></td><td>最大HP、物理防御、HP回复</td></tr><tr><td><strong>适合职业</strong></td><td>剑士、牧师、所有职业</td></tr><tr><td><strong>加点优先级</strong></td><td>坦克 &gt; 近战 &gt; 远程</td></tr><tr><td><strong>每点收益</strong></td><td>HP +50, DEF +1, HP回复+</td></tr></tbody></table><p><strong>适合场景</strong>：</p><ul><li>前排坦克</li><li>PvP需要生存的职业</li><li>任何需要提高容错率的BD</li></ul><h3 id="int-智力" tabindex="-1">INT（智力） <a class="header-anchor" href="#int-智力" aria-label="Permalink to &quot;INT（智力）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>主要影响</strong></td><td>魔法攻击力、最大SP、SP回复</td></tr><tr><td><strong>适合职业</strong></td><td>法师、牧师、贤者</td></tr><tr><td><strong>加点优先级</strong></td><td>法系职业 &gt; 物理职业不点</td></tr><tr><td><strong>每点收益</strong></td><td>MATK +2, SP +10, SP回复+</td></tr></tbody></table><p><strong>适合场景</strong>：</p><ul><li>魔法输出（巫师、贤者）</li><li>治疗职业（牧师）</li><li>需要频繁使用技能的BD</li></ul><h3 id="dex-灵巧" tabindex="-1">DEX（灵巧） <a class="header-anchor" href="#dex-灵巧" aria-label="Permalink to &quot;DEX（灵巧）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>主要影响</strong></td><td>命中率、远程攻击力、施法速度</td></tr><tr><td><strong>适合职业</strong></td><td>弓箭手、法师、所有职业</td></tr><tr><td><strong>加点优先级</strong></td><td>远程职业 &gt; 法系 &gt; 物理近战</td></tr><tr><td><strong>每点收益</strong></td><td>命中 +1, 远程ATK +1, 施法速度+</td></tr></tbody></table><p><strong>适合场景</strong>：</p><ul><li>远程物理输出（猎人）</li><li>需要施法速度的法系</li><li>任何需要命中的BD</li></ul><h3 id="luk-幸运" tabindex="-1">LUK（幸运） <a class="header-anchor" href="#luk-幸运" aria-label="Permalink to &quot;LUK（幸运）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>主要影响</strong></td><td>暴击率、暴击伤害、掉宝率</td></tr><tr><td><strong>适合职业</strong></td><td>刺客、弓箭手、商人</td></tr><tr><td><strong>加点优先级</strong></td><td>暴击流 &gt; 打钱流 &gt; 其他</td></tr><tr><td><strong>每点收益</strong></td><td>暴击率 +0.3%, 暴击伤害 +0.5%, 掉宝率+</td></tr></tbody></table><p><strong>适合场景</strong>：</p><ul><li>暴击流输出（刺客拳刃、弓箭手角弓）</li><li>打钱/刷宝BD</li><li>需要暴击触发的技能</li></ul><h2 id="职业加点参考" tabindex="-1">职业加点参考 <a class="header-anchor" href="#职业加点参考" aria-label="Permalink to &quot;职业加点参考&quot;">​</a></h2><h3 id="物理近战" tabindex="-1">物理近战 <a class="header-anchor" href="#物理近战" aria-label="Permalink to &quot;物理近战&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业流派</th><th>STR</th><th>AGI</th><th>VIT</th><th>INT</th><th>DEX</th><th>LUK</th></tr></thead><tbody><tr><td>剑士坦克</td><td>20</td><td>30</td><td>99</td><td>10</td><td>40</td><td>1</td></tr><tr><td>剑士力量</td><td>80</td><td>50</td><td>50</td><td>1</td><td>40</td><td>20</td></tr><tr><td>刺客暴击</td><td>50</td><td>90</td><td>20</td><td>1</td><td>30</td><td>70</td></tr><tr><td>刺客双刀</td><td>80</td><td>60</td><td>30</td><td>1</td><td>50</td><td>20</td></tr></tbody></table><h3 id="物理远程" tabindex="-1">物理远程 <a class="header-anchor" href="#物理远程" aria-label="Permalink to &quot;物理远程&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业流派</th><th>STR</th><th>AGI</th><th>VIT</th><th>INT</th><th>DEX</th><th>LUK</th></tr></thead><tbody><tr><td>弓箭手暴击</td><td>20</td><td>90</td><td>20</td><td>1</td><td>60</td><td>60</td></tr><tr><td>弓箭手敏弓</td><td>20</td><td>90</td><td>30</td><td>1</td><td>80</td><td>20</td></tr></tbody></table><h3 id="法系" tabindex="-1">法系 <a class="header-anchor" href="#法系" aria-label="Permalink to &quot;法系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业流派</th><th>STR</th><th>AGI</th><th>VIT</th><th>INT</th><th>DEX</th><th>LUK</th></tr></thead><tbody><tr><td>法师输出</td><td>1</td><td>20</td><td>30</td><td>99</td><td>40</td><td>1</td></tr><tr><td>牧师纯奶</td><td>10</td><td>1</td><td>60</td><td>99</td><td>30</td><td>1</td></tr><tr><td>牧师驱魔</td><td>10</td><td>20</td><td>30</td><td>99</td><td>40</td><td>20</td></tr></tbody></table><h3 id="特殊" tabindex="-1">特殊 <a class="header-anchor" href="#特殊" aria-label="Permalink to &quot;特殊&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业流派</th><th>STR</th><th>AGI</th><th>VIT</th><th>INT</th><th>DEX</th><th>LUK</th></tr></thead><tbody><tr><td>商人打钱</td><td>50</td><td>20</td><td>30</td><td>1</td><td>30</td><td>30</td></tr><tr><td>铁匠战斗</td><td>80</td><td>40</td><td>40</td><td>1</td><td>30</td><td>1</td></tr></tbody></table><h2 id="属性收益规律" tabindex="-1">属性收益规律 <a class="header-anchor" href="#属性收益规律" aria-label="Permalink to &quot;属性收益规律&quot;">​</a></h2><h3 id="非线性收益" tabindex="-1">非线性收益 <a class="header-anchor" href="#非线性收益" aria-label="Permalink to &quot;非线性收益&quot;">​</a></h3><p>RO3的属性点收益遵循<strong>递减规律</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1-50点：  高收益期（每点收益100%）</span></span>
<span class="line"><span>50-80点： 中收益期（每点收益70%）</span></span>
<span class="line"><span>80-99点： 低收益期（每点收益50%）</span></span></code></pre></div><p><strong>策略建议</strong>：</p><ul><li>主属性点到80即可转点副属性</li><li>除非是极限BD（如纯VIT坦克），不建议点到99</li><li>适当补短板属性比极限一项更有效率</li></ul><h3 id="边际效益举例" tabindex="-1">边际效益举例 <a class="header-anchor" href="#边际效益举例" aria-label="Permalink to &quot;边际效益举例&quot;">​</a></h3><p>以STR为例：</p><table tabindex="0"><thead><tr><th>STR值</th><th>ATK加成</th><th>每点收益</th></tr></thead><tbody><tr><td>1→50</td><td>+100 ATK</td><td>2.0 ATK/点</td></tr><tr><td>50→80</td><td>+42 ATK</td><td>1.4 ATK/点</td></tr><tr><td>80→99</td><td>+19 ATK</td><td>1.0 ATK/点</td></tr></tbody></table><blockquote><p><strong>核心原则</strong>：不要照搬别人的加点方案。根据自己的装备、卡片和玩法风格灵活调整，才是最优解。</p></blockquote>`,47)])])}const T=a(o,[["render",l]]);export{c as __pageData,T as default};
